package com.healthsystem.ehr.graphql;

import com.healthsystem.ehr.model.MedicalEncounter;
import com.healthsystem.ehr.repository.MedicalEncounterRepository;
import com.healthsystem.ehr.service.ClinicalAccessService;
import org.springframework.graphql.data.method.annotation.Argument;
import org.springframework.graphql.data.method.annotation.QueryMapping;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;

@Controller
public class MedicalEncounterGraphQLResolver {

    private final MedicalEncounterRepository encounterRepository;
    private final ClinicalAccessService clinicalAccessService;

    public MedicalEncounterGraphQLResolver(MedicalEncounterRepository encounterRepository, ClinicalAccessService clinicalAccessService) {
        this.encounterRepository = encounterRepository;
        this.clinicalAccessService = clinicalAccessService;
    }

    @QueryMapping
    public MedicalEncounter patientEncounter(
            @Argument Long encounterId,
            Authentication authentication) {
        MedicalEncounter encounter = encounterRepository.findById(encounterId)
                .orElseThrow(() -> new IllegalArgumentException("Medical encounter not found"));
        if (!clinicalAccessService.hasEncounterAccess(authentication.getName(), encounter)) {
            throw new AccessDeniedException("User does not have an active clinical care relationship or ownership of encounter " + encounterId);
        }
        return encounter;
    }
}
